#include <WiFi.h>
#include <time.h>

const char* WIFI_NAME = "your-wifi";       // ask your teacher
const char* WIFI_PASSWORD = "your-password";

void setup() {
  Serial.begin(115200);
  WiFi.begin(WIFI_NAME, WIFI_PASSWORD);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
  }
  // Melbourne time, with daylight saving.
  configTime(0, 0, "pool.ntp.org");
  setenv("TZ", "AEST-10AEDT,M10.1.0,M4.1.0/3", 1);
  tzset();
}

void loop() {
  time_t now = time(nullptr);   // seconds since 1970
  struct tm t;
  localtime_r(&now, &t);        // split into hours, minutes...
  if (t.tm_year > 100) {        // the year counts from 1900, so the time has arrived
    Serial.printf("%02d:%02d:%02d\n", t.tm_hour, ___, t.tm_sec);
  } else {
    Serial.println("Waiting for the time...");
  }
  delay(1000);
}

